import{_ as l,o as i,c as t,a0 as o}from"./chunks/framework.CShDTZbC.js";const p=JSON.parse('{"title":"附录 C · 避坑自查清单（可打印版）","description":"","frontmatter":{},"headers":[],"relativePath":"book/appendix/c-checklists.md","filePath":"book/appendix/c-checklists.md","lastUpdated":1788537144000}'),e={name:"book/appendix/c-checklists.md"};function r(s,a,n,c,h,d){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="附录-c-·-避坑自查清单-可打印版" tabindex="-1">附录 C · 避坑自查清单（可打印版） <a class="header-anchor" href="#附录-c-·-避坑自查清单-可打印版" aria-label="Permalink to &quot;附录 C · 避坑自查清单（可打印版）&quot;">​</a></h1><blockquote><p>第 10 章（八大坑）与第 20/24 章（AI 验货）的清单合集。<strong>每个策略上线回测前，从头过一遍。</strong></p></blockquote><h2 id="一、策略回测八查-源自第-10-章" tabindex="-1">一、策略回测八查（源自第 10 章） <a class="header-anchor" href="#一、策略回测八查-源自第-10-章" aria-label="Permalink to &quot;一、策略回测八查（源自第 10 章）&quot;">​</a></h2><ul><li>[ ] <strong>未来函数</strong>：算信号的每一根数据，在决策时刻都发生了吗？（<code>shift</code> 了吗？）</li><li>[ ] <strong>过拟合</strong>：参数做过敏感性测试吗？留样本外数据了吗？</li><li>[ ] <strong>幸存者偏差</strong>：股票池含退市/ST 股吗？</li><li>[ ] <strong>偷价成交</strong>：成交价假设现实吗（收盘信号次日成交）？</li><li>[ ] <strong>滑点手续费</strong>：佣金、印花税、滑点都设了吗？</li><li>[ ] <strong>数据乌龙</strong>：复权处理了吗？缺口和异常值检查了吗？</li><li>[ ] <strong>样本外失灵</strong>：分年度收益拆过吗？牛/熊/震荡分别表现如何？</li><li>[ ] <strong>心态预案</strong>：执行纪律写下来了吗？回撤多少必须停下来 review？</li></ul><h2 id="二、ai-生成代码三道关卡-源自第-20-章" tabindex="-1">二、AI 生成代码三道关卡（源自第 20 章） <a class="header-anchor" href="#二、ai-生成代码三道关卡-源自第-20-章" aria-label="Permalink to &quot;二、AI 生成代码三道关卡（源自第 20 章）&quot;">​</a></h2><h3 id="第一关-·-机器检查" tabindex="-1">第一关 · 机器检查 <a class="header-anchor" href="#第一关-·-机器检查" aria-label="Permalink to &quot;第一关 · 机器检查&quot;">​</a></h3><ul><li>[ ] 静态扫描：未 shift 的信号、<code>shift(-n)</code> 用法、除零、空值</li><li>[ ] API 核对：每个函数都在平台文档里真实存在</li><li>[ ] 成本假设已设置且合理</li></ul><h3 id="第二关-·-数据检查" tabindex="-1">第二关 · 数据检查 <a class="header-anchor" href="#第二关-·-数据检查" aria-label="Permalink to &quot;第二关 · 数据检查&quot;">​</a></h3><ul><li>[ ] 分年度收益拆解，不是只赚一段</li><li>[ ] 参数动一动，结果不剧变</li><li>[ ] 与买入持有基准对比过</li></ul><h3 id="第三关-·-人工审查" tabindex="-1">第三关 · 人工审查 <a class="header-anchor" href="#第三关-·-人工审查" aria-label="Permalink to &quot;第三关 · 人工审查&quot;">​</a></h3><ul><li>[ ] 每一行都能讲给自己听</li><li>[ ] 与策略逻辑说明书逐条对照</li><li>[ ] 回答得了&quot;这钱是谁亏的&quot;</li></ul><h2 id="三、ai-幻觉速查-源自第-20-24-章" tabindex="-1">三、AI 幻觉速查（源自第 20/24 章） <a class="header-anchor" href="#三、ai-幻觉速查-源自第-20-24-章" aria-label="Permalink to &quot;三、AI 幻觉速查（源自第 20/24 章）&quot;">​</a></h2><ul><li>[ ] 📅 时序幻觉：信号时点检查过</li><li>[ ] 📚 API 幻觉：函数名对照文档抽查过</li><li>[ ] 📉 数据幻觉：AI 给的&quot;历史战绩&quot;用真实数据复核过</li><li>[ ] 🧮 逻辑幻觉：代码行为与策略说明书一致</li></ul><hr><div class="tip custom-block"><p class="custom-block-title">💡 用法建议</p><p>打印出来，每跑一个新策略勾一遍。<strong>连续三个策略都在同一项翻车，就回去重读对应章节。</strong></p></div>',15)])])}const b=l(e,[["render",r]]);export{p as __pageData,b as default};
